package com.campusplacement.controller;
import com.campusplacement.dto.ApiResponse; import com.campusplacement.entity.Student; import com.campusplacement.repository.*; import com.campusplacement.service.PlacementService; import org.springframework.web.bind.annotation.*; import org.springframework.web.multipart.MultipartFile; import java.io.*; import java.util.*;
@RestController @RequestMapping("/students")
public class StudentController {
 private final StudentRepository repo; private final PlacementService placement; private final ApplicationRepository apps; private final InterviewRepository interviews; private final PlacementResultRepository results; private final NotificationRepository notifications;
 public StudentController(StudentRepository r,PlacementService p,ApplicationRepository a,InterviewRepository i,PlacementResultRepository pr,NotificationRepository n){repo=r;placement=p;apps=a;interviews=i;results=pr;notifications=n;}
 @GetMapping public List<Student> all(){return repo.findAll();}
 @GetMapping("/{id}") public ApiResponse one(@PathVariable Integer id){Student s=repo.findById(id).orElseThrow(()->new IllegalArgumentException("Student not found"));s.setPassword(null);return new ApiResponse(true,"OK",s);}
 @PutMapping("/{id}") public ApiResponse update(@PathVariable Integer id,@RequestBody Student input){Student s=repo.findById(id).orElseThrow(()->new IllegalArgumentException("Student not found"));input.setId(id);input.setPassword(s.getPassword());if(input.getResume()==null)input.setResume(s.getResume());Student saved=repo.save(input);saved.setPassword(null);return new ApiResponse(true,"Profile updated",saved);}
 @PostMapping("/{id}/resume") public ApiResponse resume(@PathVariable Integer id,@RequestParam("file") MultipartFile file)throws IOException{if(file.isEmpty())throw new IllegalArgumentException("Choose a file");String name=file.getOriginalFilename();if(name==null||!name.toLowerCase().endsWith(".pdf"))throw new IllegalArgumentException("Only PDF resumes are allowed");File dir=new File("uploads");if(!dir.exists())dir.mkdirs();String safe=id+"_"+name.replaceAll("[^a-zA-Z0-9._-]","_");file.transferTo(new File(dir,safe));Student s=repo.findById(id).orElseThrow(()->new IllegalArgumentException("Student not found"));s.setResume(safe);repo.save(s);return new ApiResponse(true,"Resume uploaded",safe);}
 @GetMapping("/{id}/applications") public List<?> applications(@PathVariable Integer id){return apps.findByStudentId(id).stream().map(a->{Map<String,Object> m=new LinkedHashMap<>();m.put("id",a.getId());m.put("driveId",a.getDrive().getId());m.put("company",a.getDrive().getCompany().getName());m.put("role",a.getDrive().getJobRole());m.put("appliedDate",a.getAppliedDate());m.put("status",a.getStatus());m.put("registrationDetails",a.getRegistrationDetails());m.put("applicationLink",a.getDrive().getApplicationLink());return m;}).collect(java.util.stream.Collectors.toList());}
 @GetMapping("/{id}/interviews") public List<?> interviews(@PathVariable Integer id){return interviews.findByStudentId(id).stream().map(i->{Map<String,Object> m=new LinkedHashMap<>();m.put("id",i.getId());m.put("company",i.getDrive().getCompany().getName());m.put("role",i.getDrive().getJobRole());m.put("round",i.getRound());m.put("date",i.getInterviewDate());m.put("time",i.getInterviewTime());m.put("venue",i.getVenue());m.put("meetingLink",i.getMeetingLink());m.put("type",i.getType());m.put("status",i.getStatus());return m;}).collect(java.util.stream.Collectors.toList());}
 @GetMapping("/{id}/results") public List<?> results(@PathVariable Integer id){return results.findByStudentId(id).stream().map(r->{Map<String,Object> m=new LinkedHashMap<>();m.put("id",r.getId());m.put("company",r.getDrive().getCompany().getName());m.put("role",r.getDrive().getJobRole());m.put("package",r.getPackageValue());m.put("status",r.getStatus());m.put("joiningDate",r.getJoiningDate());return m;}).collect(java.util.stream.Collectors.toList());}
 @GetMapping("/{id}/notifications") public List<?> notifications(@PathVariable Integer id){return notifications.findByStudentIdOrStudentIsNullOrderByCreatedDateDesc(id);}
 @PutMapping("/{id}/notifications/{notificationId}/read") public ApiResponse read(@PathVariable Integer id,@PathVariable Integer notificationId){com.campusplacement.entity.Notification n=notifications.findById(notificationId).orElseThrow(()->new IllegalArgumentException("Notification not found"));n.setRead(true);return new ApiResponse(true,"Marked as read",notifications.save(n));}
}
